module.exports = {
  async up(queryInterface) {
    const [results] = await queryInterface.sequelize.query(
      "SELECT COUNT(*) as cnt FROM locations WHERE location_code IN ('GOA','DEL','BOM')"
    );
    const cnt = parseInt(results[0].cnt ?? results[0].CNT ?? 0, 10);
    if (cnt > 0) {
      console.log('Locations already seeded, skipping.');
      return;
    }

    const now = new Date();
    await queryInterface.bulkInsert('locations', rows.map((r) => ({
      location_code:      r.code,
      location_name:      r.name,
      country:            r.country,
      type:               r.type,
      map_link:           null,
      location_image:     r.img,
      description:        r.desc,
      famous_sightseens:  JSON.stringify(r.sights),
      is_online:          r.online ? 1 : 0,
      status:             'ACTIVE',
      remarks:            null,
      created_by:         null,
      updated_by:         null,
      created_at:         now,
      updated_at:         now,
      deleted_at:         null,
    })));

    console.log(`Seeded ${rows.length} locations.`);
  },

  async down(queryInterface) {
    const codes = rows.map((r) => r.code);
    await queryInterface.sequelize.query(
      `DELETE FROM locations WHERE location_code IN (${codes.map(() => '?').join(',')})`,
      { replacements: codes }
    );
  },
};
